/* NOTICE: This file was generated by an LLM coding system on 2026-08-15. */
/* Draws the charts on /meta-analytics/ and fills the word lists.
 *
 * Data comes from meta-analytics/data/{links,words}.json, which
 * meta_analytics_source/build_data.py writes and a GitHub Action refreshes.
 *
 * Everything here is hand-rolled SVG on purpose: no charting library, no CDN.
 * Two chart types share the frame and axis helpers below:
 *
 *   drawPlot      scatter -- outbound domains, and word frequency vs. rank
 *   drawLollipop  paired horizontal rows -- expected vs. actual word rates
 */
(function () {
  "use strict";

  // Golden ratio. Every chart is PLOT_W wide and PLOT_W / PHI tall in user
  // units; the SVG scales to whatever width the container gives it.
  var PHI = 1.6180339887;
  var PLOT_W = 640;
  var PLOT_H = Math.round(PLOT_W / PHI); // 396

  // The top margin holds the y-axis title, which is written horizontally on
  // its own line or two rather than rotated up the side -- rotated axis titles
  // are the single most reliable way to make a reader tilt their head.
  var MARGIN = { top: 38, right: 16, bottom: 44, left: 52 };
  var INNER_W = PLOT_W - MARGIN.left - MARGIN.right;
  var INNER_H = PLOT_H - MARGIN.top - MARGIN.bottom;
  var TITLE_LINE_H = 13;

  var SVG_NS = "http://www.w3.org/2000/svg";

  function el(name, attrs, text) {
    var node = document.createElementNS(SVG_NS, name);
    for (var key in attrs) {
      if (attrs[key] !== null && attrs[key] !== undefined) {
        node.setAttribute(key, attrs[key]);
      }
    }
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function num(n) {
    return n.toLocaleString("en-US");
  }

  function plural(n, one, many) {
    return num(n) + " " + (n === 1 ? one : many);
  }

  // Rates run from hundredths to thousands per million, so they need more
  // precision at the small end than at the large one.
  function rate(v) {
    if (v >= 100) return num(Math.round(v));
    if (v >= 1) return v.toFixed(1);
    return v.toFixed(2);
  }

  // Deterministic pseudo-random in [0, 1) from an integer. Jitter has to be
  // stable across page loads: a dot that moves when you look away is a dot
  // whose position you cannot trust, and the hover highlight would drift with
  // it. This is the usual sin-hash; its quality is irrelevant here, only its
  // repeatability.
  function noise(i) {
    var x = Math.sin(i * 12.9898 + 4.1414) * 43758.5453;
    return x - Math.floor(x);
  }

  // --- scales -------------------------------------------------------------

  function linearScale(d0, d1, r0, r1) {
    var span = d1 - d0 || 1;
    return function (v) {
      return r0 + ((v - d0) / span) * (r1 - r0);
    };
  }

  function logScale(d0, d1, r0, r1) {
    var l0 = Math.log10(d0);
    var span = Math.log10(d1) - l0 || 1;
    return function (v) {
      return r0 + ((Math.log10(v) - l0) / span) * (r1 - r0);
    };
  }

  function clamp(v, lo, hi) {
    return v < lo ? lo : v > hi ? hi : v;
  }

  // Ticks at 1, 2, 5, 10, 20, 50, ... within [lo, hi]. Decade-only ticks leave
  // a log axis with two or three labels on a range this short; the 1-2-5
  // sequence keeps it readable without crowding.
  function logTicks(lo, hi, steps) {
    var ticks = [];
    steps = steps || [1, 2, 5];
    for (var exp = Math.floor(Math.log10(lo)); exp <= Math.ceil(Math.log10(hi)); exp++) {
      for (var i = 0; i < steps.length; i++) {
        var value = steps[i] * Math.pow(10, exp);
        if (value >= lo && value <= hi) ticks.push(value);
      }
    }
    return ticks;
  }

  // --- shared chart frame -------------------------------------------------

  /* Draws axes, ticks, and titles into a fresh <svg> and returns it.
   *
   * frame: { margin, xTicks, yTicks, xLabel, yLabel (string or array of
   *          lines), ariaLabel, drawYAxisLine }
   */
  function drawFrame(frame) {
    var m = frame.margin || MARGIN;
    var innerW = PLOT_W - m.left - m.right;
    var innerH = PLOT_H - m.top - m.bottom;

    var svg = el("svg", {
      viewBox: "0 0 " + PLOT_W + " " + PLOT_H,
      preserveAspectRatio: "xMidYMid meet",
      role: "img",
      "aria-label": frame.ariaLabel
    });

    var axes = el("g", { class: "meta-axis" });
    svg.appendChild(axes);

    axes.appendChild(
      el("line", { x1: m.left, y1: m.top + innerH, x2: m.left + innerW, y2: m.top + innerH })
    );
    (frame.xTicks || []).forEach(function (tick) {
      var x = frame.xScale(tick.value);
      axes.appendChild(el("line", { x1: x, y1: m.top + innerH, x2: x, y2: m.top + innerH + 5 }));
      axes.appendChild(
        el("text", { x: x, y: m.top + innerH + 18, "text-anchor": "middle" }, tick.label)
      );
    });
    axes.appendChild(
      el(
        "text",
        {
          class: "meta-axis-title",
          x: m.left + innerW / 2,
          y: PLOT_H - 4,
          "text-anchor": "middle"
        },
        frame.xLabel
      )
    );

    if (frame.drawYAxisLine !== false) {
      axes.appendChild(el("line", { x1: m.left, y1: m.top, x2: m.left, y2: m.top + innerH }));
    }
    (frame.yTicks || []).forEach(function (tick) {
      var y = frame.yScale(tick.value);
      axes.appendChild(el("line", { x1: m.left - 5, y1: y, x2: m.left, y2: y }));
      axes.appendChild(el("text", { x: m.left - 9, y: y + 4, "text-anchor": "end" }, tick.label));
    });

    // The y-axis title, upright, stacked above the axis it labels. Bottom line
    // sits just clear of the plot area; extra lines stack upward from there.
    var lines = [].concat(frame.yLabel);
    lines.forEach(function (line, i) {
      axes.appendChild(
        el(
          "text",
          {
            class: "meta-axis-title",
            x: 0,
            y: m.top - 10 - (lines.length - 1 - i) * TITLE_LINE_H,
            "text-anchor": "start"
          },
          line
        )
      );
    });

    return svg;
  }

  /* Attaches the shared hover behavior.
   *
   * One transparent rect catches the pointer for the whole plot area and the
   * nearest mark is found by scanning `points` (each carrying px/py). Hit
   * testing the marks themselves does not work: at these densities they are
   * 1-3px across and often overlap.
   */
  function attachHover(container, svg, points, opts) {
    var m = opts.margin || MARGIN;
    var innerW = PLOT_W - m.left - m.right;
    var innerH = PLOT_H - m.top - m.bottom;
    var reach = opts.reach || 30;

    var highlight = opts.highlight || el("circle", { class: "meta-highlight", r: 5 });
    highlight.setAttribute("opacity", 0);
    svg.appendChild(highlight);

    svg.appendChild(
      el("rect", { x: m.left, y: m.top, width: innerW, height: innerH, fill: "transparent" })
    );

    var tooltip = document.createElement("div");
    tooltip.className = "meta-tooltip";
    container.appendChild(tooltip);

    function hide() {
      tooltip.setAttribute("data-visible", "false");
      highlight.setAttribute("opacity", 0);
    }
    hide();

    svg.addEventListener("pointermove", function (event) {
      var box = svg.getBoundingClientRect();
      if (!box.width) return;
      // Client pixels -> viewBox units. preserveAspectRatio keeps the aspect
      // fixed, so one shared factor covers both directions.
      var scale = PLOT_W / box.width;
      var mx = (event.clientX - box.left) * scale;
      var my = (event.clientY - box.top) * scale;

      var best = null;
      var bestDist = Infinity;
      for (var i = 0; i < points.length; i++) {
        var dx = points[i].px - mx;
        var dy = (opts.rowMode ? 0 : points[i].py - my) * 1;
        var dist = dx * dx + dy * dy;
        if (opts.rowMode) dist = Math.abs(points[i].py - my) * 1000 + Math.abs(dx);
        if (dist < bestDist) {
          bestDist = dist;
          best = points[i];
        }
      }
      if (!best || bestDist > (opts.rowMode ? 9000 : reach * reach)) {
        hide();
        return;
      }

      opts.place(highlight, best);
      highlight.setAttribute("opacity", 1);
      tooltip.innerHTML = opts.tooltip(best);
      tooltip.setAttribute("data-visible", "true");
      tooltip.style.left = clamp(best.px / scale, 40, box.width - 40) + "px";
      tooltip.style.top = best.py / scale - 10 + "px";
    });
    svg.addEventListener("pointerleave", hide);
  }

  // --- scatter ------------------------------------------------------------

  function drawPlot(spec) {
    var container = spec.container;
    container.textContent = "";
    container.classList.add("meta-plot", "meta-plot--" + spec.modifier);

    var svg = drawFrame(spec);
    if (spec.decorate) spec.decorate(svg);

    var marks = el("g", {});
    spec.points.forEach(function (point, i) {
      point.px = spec.jitter ? spec.jitter(point, i) : spec.xScale(point.x);
      point.py = spec.yScale(point.y);
      marks.appendChild(el("circle", { class: "meta-dot", cx: point.px, cy: point.py, r: point.r }));
    });
    svg.appendChild(marks);
    container.appendChild(svg);

    attachHover(container, svg, spec.points, {
      tooltip: spec.tooltip,
      place: function (node, point) {
        node.setAttribute("cx", point.px);
        node.setAttribute("cy", point.py);
      }
    });
  }

  // --- section 1: outbound links -----------------------------------------

  function renderLinks(data) {
    document.getElementById("links-count").textContent = num(data.total_links);
    document.getElementById("links-domains").textContent = num(data.total_domains);
    document.getElementById("links-unique").textContent = num(data.total_unique_urls);

    var domains = data.domains;
    var maxCount = domains[0].count;

    // x: links per domain, log -- the top domain has ~2 orders of magnitude
    // more links than the long tail, which a linear axis would flatten into a
    // single column against the left edge. The domain is padded past the data
    // on both sides so each integer count's band (below) fits inside the axis.
    var xScale = logScale(0.72, maxCount * 1.3, MARGIN.left, MARGIN.left + INNER_W);
    // y: rank, 1 at the top.
    var yScale = linearScale(1, domains.length, MARGIN.top + 6, MARGIN.top + INNER_H - 6);

    // Link counts are integers, so without help every domain linked once lands
    // on the same pixel column: 74 dots stacked into what reads as a solid
    // bar. Each count c gets the band of x-positions that would round to it,
    // [c-0.5, c+0.5], and its dots are spread across that band. The hairlines
    // at the band edges are what keep this readable rather than merely
    // decorative -- they mark exactly where one count ends and the next
    // begins, so a dot's true value is still recoverable by eye.
    //
    // Only the low counts need any of this. On a log axis the band around 60
    // links is a pixel wide, so those dots are already unambiguous; spreading
    // and fencing them would add clutter that carries no information. MIN_BAND
    // is the width below which a band is left alone.
    var MIN_BAND = 6;

    function band(count) {
      var b = {
        lo: clamp(xScale(count - 0.5), MARGIN.left, MARGIN.left + INNER_W),
        hi: clamp(xScale(count + 0.5), MARGIN.left, MARGIN.left + INNER_W)
      };
      b.wide = b.hi - b.lo >= MIN_BAND;
      return b;
    }

    var points = domains.map(function (d, i) {
      return { x: d.count, y: i + 1, r: 3, data: d };
    });

    var yTicks = [1, 25, 50, 75, 100, 125]
      .filter(function (v) {
        return v <= domains.length;
      })
      .map(function (v) {
        return { value: v, label: String(v) };
      });

    drawPlot({
      container: document.getElementById("links-plot"),
      modifier: "links",
      ariaLabel:
        "Scatter plot of " +
        num(domains.length) +
        " outbound domains, ranked by how many links point at each.",
      points: points,
      xScale: xScale,
      yScale: yScale,
      xTicks: logTicks(1, maxCount).map(function (v) {
        return { value: v, label: num(v) };
      }),
      yTicks: yTicks,
      xLabel: "Links to that domain",
      yLabel: "Rank",
      // Hairlines first, so the dots sit on top of them.
      decorate: function (svg) {
        var drawn = {};
        var group = el("g", { class: "meta-band" });
        points.forEach(function (point) {
          if (drawn[point.x]) return;
          drawn[point.x] = true;
          var b = band(point.x);
          if (!b.wide) return;
          [b.lo, b.hi].forEach(function (x) {
            group.appendChild(
              el("line", { x1: x, y1: MARGIN.top, x2: x, y2: MARGIN.top + INNER_H })
            );
          });
        });
        svg.appendChild(group);
      },
      jitter: function (point, i) {
        var b = band(point.x);
        if (!b.wide) return xScale(point.x);
        var pad = 3;
        return b.lo + pad + noise(i + 1) * (b.hi - b.lo - 2 * pad);
      },
      tooltip: function (point) {
        return (
          "<b>" +
          escapeHtml(point.data.domain) +
          "</b><br><span>" +
          plural(point.data.count, "link", "links") +
          " &middot; " +
          plural(point.data.unique, "unique URL", "unique URLs") +
          "</span>"
        );
      }
    });
  }

  // --- section 2: word frequencies ---------------------------------------

  function renderWords(data) {
    document.getElementById("words-total").textContent = num(data.total_words);
    document.getElementById("words-unique").textContent = num(data.unique_words);
    document.getElementById("words-files").textContent = num(data.file_count);

    var words = data.words;
    var maxRank = words.length;
    var maxFreq = words[0][1];

    var xScale = logScale(1, maxRank, MARGIN.left, MARGIN.left + INNER_W);
    var yScale = logScale(1, maxFreq, MARGIN.top + INNER_H, MARGIN.top);

    var points = words.map(function (entry, i) {
      return { x: i + 1, y: entry[1], r: 1.6, data: { word: entry[0], count: entry[1] } };
    });

    drawPlot({
      container: document.getElementById("words-plot"),
      modifier: "words",
      ariaLabel:
        "Log-log scatter plot of word frequency against frequency rank for " +
        num(maxRank) +
        " distinct words, against a dashed Zipf's-law reference line.",
      points: points,
      xScale: xScale,
      yScale: yScale,
      xTicks: logTicks(1, maxRank).map(function (v) {
        return { value: v, label: num(v) };
      }),
      yTicks: logTicks(1, maxFreq).map(function (v) {
        return { value: v, label: num(v) };
      }),
      xLabel: "Frequency rank",
      yLabel: ["Times", "used"],
      // The ideal law: frequency = (frequency of the most common word) / rank,
      // a straight line of slope -1 on log-log axes.
      decorate: function (svg) {
        var path = [];
        for (var rank = 1; rank <= maxRank; rank *= 1.08) {
          var freq = maxFreq / rank;
          if (freq < 1) break;
          path.push((path.length ? "L" : "M") + xScale(rank) + " " + yScale(freq));
        }
        svg.appendChild(el("path", { class: "meta-ideal", d: path.join(" ") }));
        svg.appendChild(
          el(
            "text",
            {
              class: "meta-legend",
              x: MARGIN.left + INNER_W,
              y: MARGIN.top + 12,
              "text-anchor": "end"
            },
            "- - -  ideal Zipf's law: frequency = " + num(maxFreq) + " / rank"
          )
        );
      },
      tooltip: function (point) {
        return (
          "<b>" +
          escapeHtml(point.data.word) +
          "</b><br><span>" +
          plural(point.data.count, "time", "times") +
          " &middot; rank " +
          num(point.x) +
          "</span>"
        );
      }
    });

    renderRare(data);
    renderUnusual(data);
  }

  // --- section 3: rare words ---------------------------------------------

  var TIERS = [
    { key: "1", listId: "rare-1-list" },
    { key: "2", listId: "rare-2-list" },
    { key: "3", listId: "rare-3-list" }
  ];

  // The counts appear in more than one place per tier (the tier-1 total is
  // quoted in the section's opening paragraph as well as in its summary), so
  // they are filled by attribute rather than by id.
  function fillAll(selector, text) {
    var nodes = document.querySelectorAll(selector);
    for (var i = 0; i < nodes.length; i++) nodes[i].textContent = text;
  }

  function renderRare(data) {
    TIERS.forEach(function (tier) {
      var words = data.rare[tier.key] || [];
      var list = document.getElementById(tier.listId);
      list.textContent = "";
      words.forEach(function (word) {
        var item = document.createElement("li");
        item.textContent = word;
        list.appendChild(item);
      });
      fillAll('[data-rare-shown="' + tier.key + '"]', num(words.length));
      fillAll('[data-rare-total="' + tier.key + '"]', num(data.rare_totals[tier.key]));
    });
  }

  // --- section 4: unusual words ------------------------------------------

  /* Paired horizontal rows: one line per word, running from the rate English
   * would predict to the rate this site actually uses. Both charts share one
   * x-scale so an over-used word and an under-used one can be compared
   * directly across the two.
   */
  function drawLollipop(spec) {
    var container = spec.container;
    container.textContent = "";
    container.classList.add("meta-plot", "meta-plot--lollipop");

    var m = { top: 46, right: 20, bottom: 44, left: 108 };
    var innerW = PLOT_W - m.left - m.right;
    var innerH = PLOT_H - m.top - m.bottom;
    var rows = spec.rows;
    var step = innerH / rows.length;

    var xScale = spec.xScale;
    var yScale = function (i) {
      return m.top + step * (i + 0.5);
    };

    var svg = drawFrame({
      margin: m,
      ariaLabel: spec.ariaLabel,
      xScale: xScale,
      yScale: yScale,
      xTicks: spec.xTicks,
      yTicks: [],
      xLabel: "Occurrences per million words",
      yLabel: spec.yLabel,
      drawYAxisLine: false
    });

    var marks = el("g", {});
    var points = [];
    rows.forEach(function (row, i) {
      var y = yScale(i);
      var xe = xScale(row.expected);
      var xa = xScale(row.actual);

      marks.appendChild(el("line", { class: "meta-lolli-stem", x1: xe, y1: y, x2: xa, y2: y }));
      marks.appendChild(el("circle", { class: "meta-lolli-expected", cx: xe, cy: y, r: 3.5 }));
      marks.appendChild(el("circle", { class: "meta-lolli-actual", cx: xa, cy: y, r: 4 }));
      marks.appendChild(
        el(
          "text",
          { class: "meta-lolli-label", x: m.left - 8, y: y + 4, "text-anchor": "end" },
          row.word
        )
      );
      // Hover anchors on the actual-rate dot, which is the value being claimed.
      points.push({ px: xa, py: y, row: row, xe: xe });
    });
    svg.appendChild(marks);

    // Legend, drawn in the top margin beside the y-axis title.
    var legend = el("g", { class: "meta-legend" });
    var lx = m.left + innerW;
    legend.appendChild(el("circle", { class: "meta-lolli-actual", cx: lx - 118, cy: m.top - 22, r: 4 }));
    legend.appendChild(el("text", { x: lx - 110, y: m.top - 18 }, "here"));
    legend.appendChild(
      el("circle", { class: "meta-lolli-expected", cx: lx - 62, cy: m.top - 22, r: 3.5 })
    );
    legend.appendChild(el("text", { x: lx - 54, y: m.top - 18 }, "in English"));
    svg.appendChild(legend);

    container.appendChild(svg);

    var highlight = el("rect", {
      class: "meta-row-highlight",
      x: m.left - 104,
      y: 0,
      width: innerW + 104,
      height: step
    });
    attachHover(container, svg, points, {
      margin: m,
      rowMode: true,
      highlight: highlight,
      place: function (node, point) {
        node.setAttribute("y", point.py - step / 2);
      },
      tooltip: function (point) {
        var row = point.row;
        var times =
          row.ratio >= 1
            ? num(Math.round(row.ratio)) + "&times; more often than expected"
            : num(Math.round(1 / row.ratio)) + "&times; less often than expected";
        return (
          "<b>" +
          escapeHtml(row.word) +
          "</b> &mdash; " +
          times +
          "<br><span>" +
          rate(row.actual) +
          " per million here (" +
          plural(row.count, "use", "uses") +
          ") vs. " +
          rate(row.expected) +
          " in English</span>"
        );
      }
    });
  }

  function renderUnusual(data) {
    var unusual = data.unusual;
    if (!unusual) return;

    document.getElementById("unusual-compared").textContent = num(unusual.compared);
    document.getElementById("unusual-min").textContent = num(unusual.min_count);

    // One shared scale across both charts, padded to the nearest decade.
    var all = unusual.over.concat(unusual.under);
    var lo = Infinity;
    var hi = 0;
    all.forEach(function (row) {
      lo = Math.min(lo, row.expected, row.actual);
      hi = Math.max(hi, row.expected, row.actual);
    });
    lo = Math.pow(10, Math.floor(Math.log10(lo)));
    hi = Math.pow(10, Math.ceil(Math.log10(hi)));

    var xScale = logScale(lo, hi, 108, PLOT_W - 20);
    var xTicks = logTicks(lo, hi, [1]).map(function (v) {
      return { value: v, label: v < 1 ? String(v) : num(v) };
    });

    drawLollipop({
      container: document.getElementById("unusual-over-plot"),
      rows: unusual.over,
      xScale: xScale,
      xTicks: xTicks,
      yLabel: ["Used far more", "often than English"],
      ariaLabel:
        "The 20 words this site uses at the highest rate relative to general English, " +
        "each showing its rate here against its rate in English."
    });

    drawLollipop({
      container: document.getElementById("unusual-under-plot"),
      rows: unusual.under,
      xScale: xScale,
      xTicks: xTicks,
      yLabel: ["Used far less", "often than English"],
      ariaLabel:
        "The 20 words this site uses at the lowest rate relative to general English, " +
        "each showing its rate here against its rate in English."
    });
  }

  // --- boot ---------------------------------------------------------------

  function escapeHtml(text) {
    return text.replace(/[&<>"]/g, function (ch) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[ch];
    });
  }

  function stamp(id, iso) {
    var node = document.getElementById(id);
    if (!node) return;
    var when = new Date(iso);
    node.textContent = isNaN(when)
      ? iso
      : when.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
  }

  function fail(id, message) {
    var node = document.getElementById(id);
    if (node) {
      node.textContent = message;
      node.className = "meta-error";
    }
  }

  function load(file, onData, onError) {
    fetch(file, { cache: "no-cache" })
      .then(function (response) {
        if (!response.ok) throw new Error(response.status + " " + response.statusText);
        return response.json();
      })
      .then(onData)
      .catch(onError);
  }

  load(
    "data/links.json",
    function (data) {
      renderLinks(data);
      stamp("links-generated", data.generated);
    },
    function (error) {
      fail("links-plot", "Could not load link data (" + error.message + ").");
    }
  );

  load(
    "data/words.json",
    function (data) {
      renderWords(data);
      stamp("words-generated", data.generated);
      stamp("unusual-generated", data.generated);
    },
    function (error) {
      var message = "Could not load word data (" + error.message + ").";
      ["words-plot", "unusual-over-plot", "unusual-under-plot"].forEach(function (id) {
        fail(id, message);
      });
      TIERS.forEach(function (tier) {
        fail(tier.listId, message);
      });
    }
  );
})();
